namespace ExcelToSqlApp.Models;

public enum MappingSource
{
    /// <summary>Column is not written by the import.</summary>
    None,
    /// <summary>Value comes from an Excel column.</summary>
    Excel,
    /// <summary>Same constant value for every row.</summary>
    Constant,
    /// <summary>Generated by the import as MAX(column) + 1.</summary>
    AutoIncrement,
    /// <summary>Generated by SQL Server (IDENTITY).</summary>
    Identity,
}

public sealed class ColumnMapping
{
    public required ColumnSchema Column { get; init; }
    public string? ExcelColumn { get; set; }
    public string? ConstantValue { get; set; }
    public bool AutoIncrement { get; set; }

    /// <summary>Column participates in the duplicate check (match existing rows).</summary>
    public bool IsKey { get; set; }

    public MappingSource Source
    {
        get
        {
            if (Column.IsIdentity) return MappingSource.Identity;
            if (!Column.IsWritable) return MappingSource.None;
            if (!string.IsNullOrEmpty(ExcelColumn)) return MappingSource.Excel;
            if (!string.IsNullOrEmpty(ConstantValue)) return MappingSource.Constant;
            if (AutoIncrement && Column.CanAutoGenerate) return MappingSource.AutoIncrement;
            return MappingSource.None;
        }
    }
}
